use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let intervals = input.as_array().unwrap();
    let mut merged = Vec::new();
    let mut current = Interval::new(0, 0);

    for interval in intervals {
        let start = interval.as_array().unwrap().get(0).unwrap().as_i64().unwrap();
        let end = interval.as_array().unwrap().get(1).unwrap().as_i64().unwrap();

        if current.end < start {
            merged.push(current);
            current = Interval::new(start, end);
        } else {
            current.end = std::cmp::max(current.end, end);
        }
    }

    merged.push(current);

    let mut largest_gap = 0;
    for i in 1..merged.len() {
        let gap = merged[i].start - merged[i - 1].end;
        if gap > largest_gap {
            largest_gap = gap;
        }
    }

    Value::from(largest_gap)
}

struct Interval {
    start: i64,
    end: i64,
}

impl Interval {
    fn new(start: i64, end: i64) -> Interval {
        Interval { start, end }
    }
}
